import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"Talos-II Tianshi Academy Announcements","description":"","frontmatter":{"translationSource":{"title":"塔卫二天师府学院公告","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}]]},"headers":[],"relativePath":"talos-ii-tianshi-academy-announcements.md","filePath":"logistics/src/page-SboV353S6KTHg6EWajOub8.md"}'),n={name:"talos-ii-tianshi-academy-announcements.md"};function s(i,e,p,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="talos-ii-tianshi-academy-announcements" tabindex="-1">Talos-II Tianshi Academy Announcements <a class="header-anchor" href="#talos-ii-tianshi-academy-announcements" aria-label="Permalink to &quot;Talos-II Tianshi Academy Announcements&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>SboV353S6KTHg6EWajOub8</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-rhEbMIPJZuRyzfIw3NG0TC"></span></p><h2 id="group-announcement-text" tabindex="-1">Group Announcement Text <a class="header-anchor" href="#group-announcement-text" aria-label="Permalink to &quot;Group Announcement Text&quot;">​</a></h2><p><span class="mark-grey">*Keep the group announcement short and limited to essential information.</span></p><p>If you paid someone to build the factory for you, ask them to contact support. We aren&#39;t obliged to help paid builders make money for free.</p><p>Before asking the group for blueprint help, check relevant videos, the documentation <a href="http://43.108.59.96/" target="_blank" rel="noreferrer">http://43.108.59.96/</a>, or the wiki. Ask in the group if you still can&#39;t find the answer.</p><p>For blueprint troubleshooting, show your statistics for the following materials. You can star each item to pin it in the report. <span class="mark-yellow">Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprium Gas, Hetonite Gas, Pyrrolite Gas, SC Wuling Battery, and Jincao Solution.</span> Keep unrelated messages out of active troubleshooting.</p><p>We do not guarantee answers from members other than the support staff (group moderators). Please also understand the situation before challenging the support staff.</p><p>We can&#39;t vouch for replies or account access offered by members outside the support team (group moderators). Please hear the support team out before challenging their advice.</p><p>Indecent nicknames that violate national law or public decency are prohibited, including sexist, racist, discriminatory, abusive, violent, sexual, or regionally derogatory names. Members must change the name or be removed.</p><p>Sensitive or disturbing material is prohibited, including superstition, pornography, incitement to crime, unfamiliar links or QR codes, horror, gore, and advertisements. Violators will be removed.</p><p>Be civil. Abuse, bad-faith disruptions, rumors, personal attacks, and fights in the chat can result in a lengthy mute.</p><p><s>Discussion unrelated to factory construction is discouraged.</s> Message a moderator or group owner privately if you want to learn more or appeal a decision.</p><p>When the group fills, remove inactive members. Keep moderators and members who were active in the past week.</p><p><span id="source-block-Jhl7Wbb9J03WQtic78XjeP"></span></p><h2 id="group-moderation-rules" tabindex="-1">Group Moderation Rules <a class="header-anchor" href="#group-moderation-rules" aria-label="Permalink to &quot;Group Moderation Rules&quot;">​</a></h2><p><span class="mark-grey">*Moderation rules should clearly record possible situations and their penalties. Colored annotations may explain why a rule was adopted.</span></p><p>The rules exist to keep the support chats working. They aim to protect the groups from disruption and maintain a good atmosphere for troubleshooting. <span class="mark-sky_blue">Helping people get answers takes priority over strict enforcement for its own sake.</span></p><p>Helpers may ignore questions when the requester fails to provide the required report, ignores instructions, or asks something too simple. <strong>Challenging the moderators</strong> <span class="mark-grey">(tagging a moderator to ask a question while refusing to follow instructions)</span> earns a warning, then a two-hour mute on a repeat offense, then removal.</p><p>Once a moderator <span class="mark-red">declares a troubleshooting session open</span>, <strong>unrelated chat that disrupts it is prohibited</strong>. <span class="mark-red">The announcement itself counts as advance notice.</span> The penalties are a ten-minute mute, then one hour, then one day, then removal for continued violations. For the person receiving help, respond to unrelated comments with a reminder or warning during the session and address any penalty afterward.</p><p><strong>Sensitive material is prohibited</strong>, including <span class="mark-red">horror, gore, borderline sexual material, financial transactions, superstition, pornography, incitement to crime, unfamiliar links or QR codes, and advertisements</span>. Retract such posts whenever they appear. Mute first offenders for ten minutes and remove repeat offenders. <strong>Personal attacks are prohibited</strong> and do not require message retraction. Warn on a first offense, mute for two hours on the next, then remove the user. Moderators receive a two-hour mute in the affected chat on the first offense. On a repeat offense, revoke their moderator role and mute them in all chats for one day.</p><p>When membership reaches <span class="mark-green">475</span>, tag everyone in the morning <span class="mark-grey">(roughly 4:00–12:00)</span> to announce the cleanup and coordinate across support groups. <span class="mark-grey">Around 18:00–24:00, allowing enough time after the notice,</span> <strong>remove members</strong> who have no title and have been silent for over a week.</p><p><strong>A helper who would rather pass on a question</strong> may ignore it <span class="mark-grey">(if nobody tagged them)</span> or say they do not know the answer or have time <span class="mark-grey">(if tagged, or afterward if the timing is awkward)</span><span class="mark-grey"><s>say, 3 a.m. Beijing time</s></span><span class="mark-grey">.</span> Once a helper takes a question, they should respect the requester and take responsibility for the session. <span class="mark-red">If you can&#39;t solve a problem, identify the person taking over, tell the requester clearly, and hand it over. Avoid taking frustrations out on anyone or quitting partway through. An unexplained abandonment earns a warning, and another such incident soon afterward costs the helper their moderator role.</span></p><p>Members may <strong>invite a bot into the chat</strong> after getting permission from at least <span class="mark-sky_blue">two</span> moderators. Keep it under close supervision. For an unauthorized invitation, warn the member and remove the bot. Remove both on a repeat offense. If a bot disrupts troubleshooting, handle it as you would a disruptive member. Afterward, the support team can discuss whether to penalize the owner <span class="mark-grey">(the moderators did approve adding it, after all).</span></p><p>A <strong>repeat offense</strong> <span class="mark-grey">usually occurs within two to three days. Escalate penalties across different rules except where a first-offense warning applies. For example, after a two-hour mute for two personal attacks, disrupting troubleshooting would earn a one-day mute rather than another ten-minute mute. Conversely, someone muted for an hour for disruption who then adds a bot without permission should receive the first-offense warning and only be removed if they repeat that bot violation.</span></p><p><em>P.S. Depending on the behavior and its severity, group moderators may require a name change, mute a member, or remove them. Discuss borderline cases with the other moderators.</em></p><p><span id="source-block-vA7Yq3jYQxo0dEbUqY38XY"></span></p><h2 id="moderation-records" tabindex="-1">Moderation Records <a class="header-anchor" href="#moderation-records" aria-label="Permalink to &quot;Moderation Records&quot;">​</a></h2><p><span class="mark-grey">*Moderation records have two types. Penalty records should state the group, the member penalized, the general incident, the applicable rule (which may be omitted in obvious cases), and the penalty level. Cleanup records should state the reminder time, who performed the cleanup, and the execution time; recording cleanups is optional.</span></p></div>',1)])])}const m=a(n,[["render",s]]);export{c as __pageData,m as default};
